INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1001, 'transportation', '运输问题', 'LP', '【运输问题 Transportation Problem】\n📋 场景说明：有3个仓库（供应点）和4个客户（需求点），每个仓库有固定的供应量，每个客户有固定的需求量。从每个仓库到每个客户有不同的单位运输成本。\n\n🎯 求解目标：最小化（MINIMIZE）总运输成本。目标函数中的系数代表每条运输路线的单位成本，例如 2*x_0_0 表示从仓库0到客户0每运1单位货物花费2元。\n\n📦 决策变量说明：\n  • x_i_j（连续型，≥0）：从仓库i到客户j的运输量。例如 x_0_0 表示仓库0→客户0的运量，x_2_3 表示仓库2→客户3的运量。\n\n📐 约束条件说明：\n  • supply_i（≤约束）：每个仓库的总发货量不能超过其供应能力。例如 supply_0: x_0_0+x_0_1+x_0_2+x_0_3 ≤ 30，表示仓库0最多供应30单位。\n  • demand_j（≥约束）：每个客户的需求必须被满足。例如 demand_0: x_0_0+x_1_0+x_2_0 ≥ 20，表示客户0至少需要20单位。\n\n💡 调参建议：\n  • 增大仓库供应量（修改supply约束的rhs）可放宽供应限制\n  • 调整运输成本系数可模拟不同距离/路况\n  • 增加仓库或客户数量可扩展问题规模\n  • 推荐使用单纯形法（SimplexSolver）或内点法（InteriorPointSolver）求解', 'SimplexSolver / HiGHS', 'easy', '{"variables": [{"name": "x_0_0", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_0_1", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_0_2", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_0_3", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_1_0", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_1_1", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_1_2", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_1_3", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_2_0", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_2_1", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_2_2", "type": "CONTINUOUS", "lowerBound": 0.0}, {"name": "x_2_3", "type": "CONTINUOUS", "lowerBound": 0.0}], "constraints": [{"name": "supply_0", "expression": "x_0_0 + x_0_1 + x_0_2 + x_0_3", "type": "LEQ", "rhs": 300}, {"name": "supply_1", "expression": "x_1_0 + x_1_1 + x_1_2 + x_1_3", "type": "LEQ", "rhs": 400}, {"name": "supply_2", "expression": "x_2_0 + x_2_1 + x_2_2 + x_2_3", "type": "LEQ", "rhs": 500}, {"name": "demand_0", "expression": "x_0_0 + x_1_0 + x_2_0", "type": "GEQ", "rhs": 250}, {"name": "demand_1", "expression": "x_0_1 + x_1_1 + x_2_1", "type": "GEQ", "rhs": 350}, {"name": "demand_2", "expression": "x_0_2 + x_1_2 + x_2_2", "type": "GEQ", "rhs": 150}, {"name": "demand_3", "expression": "x_0_3 + x_1_3 + x_2_3", "type": "GEQ", "rhs": 200}], "objective": {"expression": "10*x_0_0 + 8*x_0_1 + 6*x_0_2 + 9*x_0_3 + 7*x_1_0 + 11*x_1_1 + 5*x_1_2 + 8*x_1_3 + 6*x_2_0 + 9*x_2_1 + 12*x_2_2 + 7*x_2_3", "sense": "MINIMIZE"}}', 1, 0);
INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1002, 'knapsack', '背包问题', 'MILP', '【背包问题 Knapsack Problem】\n📋 场景说明：有10个物品，每个物品有固定的重量和价值。背包有容量上限，需要决定每个物品是否放入背包。这是经典的0-1整数规划问题。\n\n🎯 求解目标：最大化（MAXIMIZE）放入背包的物品总价值。目标函数中的系数代表每个物品的价值，例如 92*x_0 表示物品0的价值为92。\n\n📦 决策变量说明：\n  • x_i（二值型 BINARY，取值0或1）：物品i是否放入背包。x_i=1表示放入，x_i=0表示不放入。共10个物品（x_0到x_9）。\n\n📐 约束条件说明：\n  • capacity（≤约束）：所有放入物品的总重量不能超过背包容量。表达式中的系数为各物品重量，例如 23*x_0 表示物品0重23，rhs=150表示背包容量为150。\n\n💡 调参建议：\n  • 增大背包容量（rhs值）可装入更多物品\n  • 修改物品价值系数可改变最优选择方案\n  • 增加物品数量可增大问题复杂度（指数级增长）\n  • 推荐使用分支定界法（BranchBoundSolver）或OR-Tools求解\n  • 由于是NP-hard问题，大规模时可尝试遗传算法（GeneticAlgorithmSolver）', 'BranchBoundSolver / OR-Tools', 'easy', '{"variables": [{"name": "x_0", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_1", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_2", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_3", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_4", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_5", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_6", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_7", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_8", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_9", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}], "constraints": [{"name": "capacity", "expression": "10*x_0 + 20*x_1 + 30*x_2 + 5*x_3 + 15*x_4 + 25*x_5 + 8*x_6 + 12*x_7 + 18*x_8 + 22*x_9", "type": "LEQ", "rhs": 50}], "objective": {"expression": "60*x_0 + 100*x_1 + 120*x_2 + 30*x_3 + 80*x_4 + 90*x_5 + 45*x_6 + 70*x_7 + 85*x_8 + 110*x_9", "sense": "MAXIMIZE"}}', 2, 0);
INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1003, 'production_scheduling', '生产排程', 'MILP', '【生产调度问题 Production Scheduling】\n📋 场景说明：工厂有3台机器和5种产品。每种产品在每台机器上的加工时间不同，每台机器每天的可用时间有限。需要决定每种产品的生产数量。\n\n🎯 求解目标：最大化（MAXIMIZE）总利润。目标函数中的系数代表每种产品的单位利润，例如 12*x_0 表示产品0每生产1单位赚12元。\n\n📦 决策变量说明：\n  • x_i（整数型 INTEGER，≥0）：产品i的生产数量。例如 x_0 的上界为50表示产品0最多生产50单位。共5种产品（x_0到x_4）。\n\n📐 约束条件说明：\n  • machine_j（≤约束）：每台机器的加工时间不能超过可用工时。表达式中的系数为每种产品在该机器上的单位加工时间，rhs为该机器的每日可用小时数。例如 machine_0: 2*x_0+3*x_1+... ≤ 480，表示机器0每天最多工作480分钟。\n  • demand_i（≤约束）：每种产品的产量不能超过市场需求上限。\n\n💡 调参建议：\n  • 增加机器工时（rhs值）可提升产能上限\n  • 调整产品利润系数可改变生产优先级\n  • 修改加工时间系数可模拟工艺改进效果\n  • 推荐使用分支定界法（BranchBoundSolver）或OR-Tools求解整数规划', 'BranchBoundSolver / PuLP', 'medium', '{"variables": [{"name": "x_0", "type": "INTEGER", "lowerBound": 5.0, "upperBound": 30.0}, {"name": "x_1", "type": "INTEGER", "lowerBound": 3.0, "upperBound": 25.0}, {"name": "x_2", "type": "INTEGER", "lowerBound": 0.0, "upperBound": 20.0}, {"name": "x_3", "type": "INTEGER", "lowerBound": 2.0, "upperBound": 15.0}, {"name": "x_4", "type": "INTEGER", "lowerBound": 0.0, "upperBound": 35.0}], "constraints": [{"name": "machine_0", "expression": "2*x_0 + 3*x_1 + x_2 + 4*x_3 + 2*x_4", "type": "LEQ", "rhs": 100}, {"name": "machine_1", "expression": "3*x_0 + 2*x_1 + 4*x_2 + x_3 + 3*x_4", "type": "LEQ", "rhs": 120}, {"name": "machine_2", "expression": "x_0 + 4*x_1 + 2*x_2 + 3*x_3 + 2*x_4", "type": "LEQ", "rhs": 80}], "objective": {"expression": "12*x_0 + 15*x_1 + 8*x_2 + 20*x_3 + 10*x_4", "sense": "MAXIMIZE"}}', 3, 0);
INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1004, 'delivery_route', '城市配送·最短路径', 'MILP', '【城市配送·最短路径规划 Vehicle Route / TSP】
📋 真实场景：某电商在广州的【配送中心 DC】需要用 1 辆货车，依次把包裹送到 4 个客户片区——天河(A)、海珠(B)、番禺(C)、白云(D)，最后返回配送中心。已知各点之间的真实行驶里程（公里），求一条总里程最短的配送路线。

🗺️ 真实距离矩阵（公里，对称）：
        DC    A     B     C     D
  DC    -     12    19    25    18
  A     12    -     10    22    15
  B     19    10    -     14    11
  C     25    22    14    -     9
  D     18    15    11    9     -

🎯 求解目标：最小化（MINIMIZE）货车总行驶里程。目标函数里 12*route_DC_A 表示「从配送中心到天河」这段走 12 公里，依此类推。

📦 决策变量（共 24 个）：
  • route_<起点>_<终点>（二值 BINARY，0或1）：货车是否从一个点直接开到另一个点。例如 route_DC_A=1 表示货车从配送中心直接开到天河；route_C_D=1 表示从番禺直接开到白云。变量名直接对应真实地点，一看就懂。
  • order_A / order_B / order_C / order_D（连续型，取值1~4）：访问顺序编号，用于消除「子环路」（防止出现 A→B→A 这种脱离主路线的小圈），这是 TSP 的经典 MTZ 技巧，初学者可暂时不用关心。

📐 约束条件（共 22 条）：
  • out_X（=1）：每个点都必须「恰好开出去一次」。
  • in_X（=1）：每个点都必须「恰好被开进来一次」。这两类约束保证每个客户都被服务、且路线首尾相连成一个完整回路。
  • mtz_X_Y（≤约束）：MTZ 子环消除约束，保证 4 个客户连成一条不断开的路线。

✅ 标准答案：最短总里程 = 63 公里，最优路线为 配送中心 → 白云(D) → 番禺(C) → 海珠(B) → 天河(A) → 配送中心。点击「求解」即可复现该结果。

💡 动手改一改，看方案如何变化（强烈建议初学者尝试）：
  1️⃣ 【改距离】把目标函数里 9*route_C_D 改成 30*route_C_D（假设番禺到白云修路堵车），重新求解：最优总里程会从 63 公里变成 77 公里，且最优路线会绕开这段拥堵路。这是最直观的一个实验。
  2️⃣ 【加客户】增加一个客户 E：新增 route_*_E / route_E_* 系列二值变量，并补充 out_E=1、in_E=1 两条约束和对应的距离系数，问题规模和最优路线都会变化（客户越多，组合数指数级增长）。
  3️⃣ 【改优化方向】把目标函数的 sense 从 MINIMIZE 改成 MAXIMIZE，会求出「最绕远的路线」，可借此理解目标函数方向对结果的决定性影响。
  4️⃣ 【改求解器】在「算法配置」里分别选 OR-Tools、分支定界(BranchBound)、PuLP 求解，对比求解速度与结果是否一致（小规模问题结果应一致，均为 63 公里）。
  5️⃣ 【放松约束】删掉所有 mtz_ 约束再求解，会得到更小的总里程（58 公里）但路线会断成几个小圈（子环路），借此直观理解 MTZ 约束「保证路线连通成一条完整回路」的作用。

🔧 推荐算法：OR-Tools / 分支定界法（BranchBoundSolver）。客户规模很大时可改用遗传算法或模拟退火做近似求解。', 'OR-Tools / BranchBoundSolver', 'medium', '{"variables": [{"name": "route_DC_A", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_DC_B", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_DC_C", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_DC_D", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_A_DC", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_A_B", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_A_C", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_A_D", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_B_DC", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_B_A", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_B_C", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_B_D", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_C_DC", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_C_A", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_C_B", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_C_D", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_D_DC", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_D_A", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_D_B", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "route_D_C", "type": "BINARY", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "order_A", "type": "CONTINUOUS", "lowerBound": 1.0, "upperBound": 4.0}, {"name": "order_B", "type": "CONTINUOUS", "lowerBound": 1.0, "upperBound": 4.0}, {"name": "order_C", "type": "CONTINUOUS", "lowerBound": 1.0, "upperBound": 4.0}, {"name": "order_D", "type": "CONTINUOUS", "lowerBound": 1.0, "upperBound": 4.0}], "constraints": [{"name": "out_DC", "expression": "route_DC_A + route_DC_B + route_DC_C + route_DC_D", "type": "EQ", "rhs": 1}, {"name": "out_A", "expression": "route_A_DC + route_A_B + route_A_C + route_A_D", "type": "EQ", "rhs": 1}, {"name": "out_B", "expression": "route_B_DC + route_B_A + route_B_C + route_B_D", "type": "EQ", "rhs": 1}, {"name": "out_C", "expression": "route_C_DC + route_C_A + route_C_B + route_C_D", "type": "EQ", "rhs": 1}, {"name": "out_D", "expression": "route_D_DC + route_D_A + route_D_B + route_D_C", "type": "EQ", "rhs": 1}, {"name": "in_DC", "expression": "route_A_DC + route_B_DC + route_C_DC + route_D_DC", "type": "EQ", "rhs": 1}, {"name": "in_A", "expression": "route_DC_A + route_B_A + route_C_A + route_D_A", "type": "EQ", "rhs": 1}, {"name": "in_B", "expression": "route_DC_B + route_A_B + route_C_B + route_D_B", "type": "EQ", "rhs": 1}, {"name": "in_C", "expression": "route_DC_C + route_A_C + route_B_C + route_D_C", "type": "EQ", "rhs": 1}, {"name": "in_D", "expression": "route_DC_D + route_A_D + route_B_D + route_C_D", "type": "EQ", "rhs": 1}, {"name": "mtz_A_B", "expression": "order_A - order_B + 4*route_A_B", "type": "LEQ", "rhs": 3}, {"name": "mtz_A_C", "expression": "order_A - order_C + 4*route_A_C", "type": "LEQ", "rhs": 3}, {"name": "mtz_A_D", "expression": "order_A - order_D + 4*route_A_D", "type": "LEQ", "rhs": 3}, {"name": "mtz_B_A", "expression": "order_B - order_A + 4*route_B_A", "type": "LEQ", "rhs": 3}, {"name": "mtz_B_C", "expression": "order_B - order_C + 4*route_B_C", "type": "LEQ", "rhs": 3}, {"name": "mtz_B_D", "expression": "order_B - order_D + 4*route_B_D", "type": "LEQ", "rhs": 3}, {"name": "mtz_C_A", "expression": "order_C - order_A + 4*route_C_A", "type": "LEQ", "rhs": 3}, {"name": "mtz_C_B", "expression": "order_C - order_B + 4*route_C_B", "type": "LEQ", "rhs": 3}, {"name": "mtz_C_D", "expression": "order_C - order_D + 4*route_C_D", "type": "LEQ", "rhs": 3}, {"name": "mtz_D_A", "expression": "order_D - order_A + 4*route_D_A", "type": "LEQ", "rhs": 3}, {"name": "mtz_D_B", "expression": "order_D - order_B + 4*route_D_B", "type": "LEQ", "rhs": 3}, {"name": "mtz_D_C", "expression": "order_D - order_C + 4*route_D_C", "type": "LEQ", "rhs": 3}], "objective": {"expression": "12*route_DC_A + 19*route_DC_B + 25*route_DC_C + 18*route_DC_D + 12*route_A_DC + 10*route_A_B + 22*route_A_C + 15*route_A_D + 19*route_B_DC + 10*route_B_A + 14*route_B_C + 11*route_B_D + 25*route_C_DC + 22*route_C_A + 14*route_C_B + 9*route_C_D + 18*route_D_DC + 15*route_D_A + 11*route_D_B + 9*route_D_C", "sense": "MINIMIZE"}}', 4, 0);
INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1005, 'resource_allocation', '资源分配', 'LP', '【资源分配问题 Resource Allocation】\n📋 场景说明：有3种资源（人力、资金、设备等）和4个项目。每种资源的总量有限，每个项目有最低资源需求。需要决定如何将资源按比例分配给各项目。\n\n🎯 求解目标：最大化（MAXIMIZE）总收益。目标函数中的系数代表将资源i分配给项目j所产生的收益，例如 5*x_0_0 表示将资源0分配给项目0的收益系数为5。\n\n📦 决策变量说明：\n  • x_i_j（连续型，0≤x≤1）：资源i分配给项目j的比例。例如 x_0_0=0.5 表示将资源0的50%分配给项目0。共12个变量（3种资源×4个项目）。\n\n📐 约束条件说明：\n  • resource_i（≤约束）：每种资源的分配比例总和不超过1（即100%）。例如 resource_0: x_0_0+x_0_1+x_0_2+x_0_3 ≤ 1。\n  • project_j（≥约束）：每个项目获得的加权资源量必须满足最低需求。例如 project_0: 100*x_0_0+80*x_1_0+200*x_2_0 ≥ 20，其中系数为各资源的单位产出能力。\n\n💡 调参建议：\n  • 提高项目需求（rhs值）会使问题更紧张，可能无解\n  • 调整收益系数可改变资源分配倾向\n  • 修改资源产出系数可模拟不同资源效率\n  • 推荐使用内点法（InteriorPointSolver）或单纯形法（SimplexSolver），这是标准线性规划问题', 'InteriorPointSolver / SimplexSolver', 'medium', '{"variables": [{"name": "x_0_0", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_0_1", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_0_2", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_0_3", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_1_0", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_1_1", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_1_2", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_1_3", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_2_0", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_2_1", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_2_2", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "x_2_3", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}], "constraints": [{"name": "resource_0", "expression": "x_0_0 + x_0_1 + x_0_2 + x_0_3", "type": "LEQ", "rhs": 1}, {"name": "resource_1", "expression": "x_1_0 + x_1_1 + x_1_2 + x_1_3", "type": "LEQ", "rhs": 1}, {"name": "resource_2", "expression": "x_2_0 + x_2_1 + x_2_2 + x_2_3", "type": "LEQ", "rhs": 1}, {"name": "project_0", "expression": "100*x_0_0 + 80*x_1_0 + 200*x_2_0", "type": "GEQ", "rhs": 20}, {"name": "project_1", "expression": "100*x_0_1 + 80*x_1_1 + 200*x_2_1", "type": "GEQ", "rhs": 15}, {"name": "project_2", "expression": "100*x_0_2 + 80*x_1_2 + 200*x_2_2", "type": "GEQ", "rhs": 25}, {"name": "project_3", "expression": "100*x_0_3 + 80*x_1_3 + 200*x_2_3", "type": "GEQ", "rhs": 10}], "objective": {"expression": "5*x_0_0 + 4*x_0_1 + 3*x_0_2 + 6*x_0_3 + 8*x_1_0 + 7*x_1_1 + 5*x_1_2 + 9*x_1_3 + 3*x_2_0 + 4*x_2_1 + 6*x_2_2 + 2*x_2_3", "sense": "MAXIMIZE"}}', 5, 0);
INSERT INTO solver_example (id, example_key, name, problem_type, description, recommended_algorithm, difficulty, problem_definition, sort_order, deleted) VALUES (1006, 'portfolio', '投资组合优化', 'QP', '【投资组合优化 Portfolio Optimization】\n📋 场景说明：有5只股票可供投资。每只股票有不同的预期收益率和风险（波动率）。股票之间存在相关性（协方差）。需要决定每只股票的投资比例。\n\n🎯 求解目标：最小化（MINIMIZE）投资组合的总风险（方差）。目标函数是二次型，包含每只股票的方差项（如 0.04*w_0²）和股票间的协方差项（如 0.02*w_0*w_1），这是经典的Markowitz均值-方差模型。\n\n📦 决策变量说明：\n  • w_i（连续型，0≤w≤1）：投资于股票i的资金比例。例如 w_0=0.3 表示将30%的资金投资于股票0。共5只股票（w_0到w_4）。\n\n📐 约束条件说明：\n  • budget（=约束）：所有股票的投资比例之和等于1，即 w_0+w_1+w_2+w_3+w_4=1，表示全部资金必须投出。\n  • target_return（≥约束）：投资组合的预期收益率不低于目标值。0.12*w_0+0.10*w_1+0.07*w_2+0.03*w_3+0.15*w_4 ≥ 0.08，表示预期收益率至少8%。其中系数为各股票的预期年化收益率。\n\n💡 调参建议：\n  • 提高目标收益率（rhs值）会迫使更多资金投入高风险股票\n  • 降低目标收益率可获得更低风险的组合\n  • 修改协方差系数可模拟不同市场环境下的股票相关性\n  • 添加单只股票上限约束（如 w_i ≤ 0.4）可实现分散投资\n  • 推荐使用内点法（InteriorPointSolver）或SciPy求解二次规划', 'InteriorPointSolver / SciPy', 'hard', '{"variables": [{"name": "w_0", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "w_1", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "w_2", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "w_3", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}, {"name": "w_4", "type": "CONTINUOUS", "lowerBound": 0.0, "upperBound": 1.0}], "constraints": [{"name": "budget", "expression": "w_0 + w_1 + w_2 + w_3 + w_4", "type": "EQ", "rhs": 1}, {"name": "target_return", "expression": "0.12*w_0 + 0.1*w_1 + 0.07*w_2 + 0.03*w_3 + 0.15*w_4", "type": "GEQ", "rhs": 0.08}], "objective": {"expression": "0.04*w_0**2 + 0.025*w_1**2 + 0.0098*w_2**2 + 0.005*w_3**2 + 0.0457*w_4**2 + 0.02*w_0*w_1 + 0.012*w_0*w_2 + 0.004*w_0*w_3 + 0.024*w_0*w_4 + 0.018*w_1*w_2 + 0.007*w_1*w_3 + 0.018*w_1*w_4 + 0.0074*w_2*w_3 + 0.0092*w_2*w_4 + 0.0058*w_3*w_4", "sense": "MINIMIZE"}}', 6, 0);
